#include "Mount/Project_JMountAttributeSet.h"
#include "Net/UnrealNetwork.h"
void UProject_JMountAttributeSet::GetLifetimeReplicatedProps(TArray<FLifetimeProperty>& OutLifetimeProps) const { Super::GetLifetimeReplicatedProps(OutLifetimeProps); DOREPLIFETIME_CONDITION_NOTIFY(UProject_JMountAttributeSet,Health,COND_None,REPNOTIFY_Always); DOREPLIFETIME_CONDITION_NOTIFY(UProject_JMountAttributeSet,MaxHealth,COND_None,REPNOTIFY_Always); DOREPLIFETIME_CONDITION_NOTIFY(UProject_JMountAttributeSet,Stamina,COND_None,REPNOTIFY_Always); DOREPLIFETIME_CONDITION_NOTIFY(UProject_JMountAttributeSet,MaxStamina,COND_None,REPNOTIFY_Always); }
void UProject_JMountAttributeSet::PreAttributeChange(const FGameplayAttribute& A,float& V){ Super::PreAttributeChange(A,V); if(A==GetHealthAttribute()) V=FMath::Clamp(V,0.f,GetMaxHealth()); else if(A==GetStaminaAttribute()) V=FMath::Clamp(V,0.f,GetMaxStamina()); else V=FMath::Max(0.f,V); }
void UProject_JMountAttributeSet::OnRep_Health(const FGameplayAttributeData& O){GAMEPLAYATTRIBUTE_REPNOTIFY(UProject_JMountAttributeSet,Health,O);} void UProject_JMountAttributeSet::OnRep_MaxHealth(const FGameplayAttributeData& O){GAMEPLAYATTRIBUTE_REPNOTIFY(UProject_JMountAttributeSet,MaxHealth,O);} void UProject_JMountAttributeSet::OnRep_Stamina(const FGameplayAttributeData& O){GAMEPLAYATTRIBUTE_REPNOTIFY(UProject_JMountAttributeSet,Stamina,O);} void UProject_JMountAttributeSet::OnRep_MaxStamina(const FGameplayAttributeData& O){GAMEPLAYATTRIBUTE_REPNOTIFY(UProject_JMountAttributeSet,MaxStamina,O);}
